101	/// The `..` in `#[func(..)]`.
102	pub struct Meta {
103	    /// Whether this function has an associated scope defined by the `#[scope]` macro.
104	    pub scope: bool,
105	    /// Whether this function is contextual.
106	    pub contextual: bool,
107	    /// The function's name as exposed to Typst.
108	    pub name: Option<String>,
109	    /// The function's title case name.
110	    pub title: Option<String>,
111	    /// The version of Typst the function was introduced in.
112	    pub since: Option<Since>,
