251	/// Produce the function's definition.
252	fn create(func: &Func, item: &syn::ItemFn) -> TokenStream {
253	    let Func { docs, vis, ident, .. } = func;
254	    let item = rewrite_fn_item(item);
255	    let ty = create_func_ty(func);
256	    let data = create_func_data(func);
257	    let oneliner = oneliner(docs);
258	
259	    let creator = if ty.is_some() {
260	        quote! {
261	            impl #foundations::NativeFunc for #ident {
262	                fn data() -> &'static #foundations::NativeFuncData {
263	                    static DATA: #foundations::NativeFuncData = #data;
264	                    &DATA
265	                }
266	            }
267	        }
268	    } else {
269	        let ident_data = quote::format_ident!("{ident}_data");
270	        quote! {
271	            #[doc(hidden)]
272	            #[expect(non_snake_case)]
273	            #vis fn #ident_data() -> &'static #foundations::NativeFuncData {
274	                static DATA: #foundations::NativeFuncData = #data;
275	                &DATA
276	            }
277	        }
278	    };
279	
280	    quote! {
281	        #[doc = #oneliner]
282	        #[expect(dead_code)]
283	        #[expect(rustdoc::broken_intra_doc_links)]
284	        #item
285	
286	        #[doc(hidden)]
287	        #ty
288	        #creator
289	    }
290	}
291	
292	/// Create native function data for the function.
293	fn create_func_data(func: &Func) -> TokenStream {
294	    let Func {
295	        ident,
296	        name,
297	        title,
298	        since,
299	        docs,
300	        keywords,
301	        returns,
302	        scope,
303	        parent,
304	        constructor,
305	        contextual,
306	        ..
307	    } = func;
308	
309	    let def_site_key = if let Some(syn::Type::Path(path)) = parent
310	        && let Some(parent) = path.path.get_ident()
311	    {
312	        format!("{parent}::{ident}")
313	    } else {
314	        ident.to_string()
315	    };
316	
317	    let scope = if *scope {
318	        quote! { <#ident as #foundations::NativeScope>::scope() }
319	    } else {
320	        quote! { #foundations::Scope::new() }
321	    };
322	
323	    let closure = create_wrapper_closure(func);
324	    let params = func
325	        .special
326	        .self_
327	        .iter()
328	        .chain(&func.params)
329	        .map(|param| create_param_info(param, &def_site_key));
330	
331	    let name = if *constructor {
332	        quote! { <#parent as #foundations::NativeType>::NAME }
333	    } else {
334	        quote! { #name }
335	    };
336	
337	    let since = if let Some(since) = since {
338	        quote! { Some(#since) }
339	    } else {
340	        quote! { None }
341	    };
342	
343	    quote! {
344	        #foundations::NativeFuncData {
345	            function: #foundations::NativeFuncPtr(&#closure),
346	            name: #name,
347	            title: #title,
348	            since: #since,
349	            docs: #docs,
350	            def_site: Some(::typst_utils::DefSite { path: file!(), key: #def_site_key }),
351	            keywords: &[#(#keywords),*],
352	            contextual: #contextual,
353	            scope: ::std::sync::LazyLock::new(&|| #scope),
354	            params: ::std::sync::LazyLock::new(&|| ::std::vec![#(#params),*]),
355	            returns:  ::std::sync::LazyLock::new(&|| <#returns as #foundations::Reflect>::output()),
356	        }
357	    }
358	}
359	
360	/// Create a type that shadows the function.
361	fn create_func_ty(func: &Func) -> Option<TokenStream> {
362	    if func.parent.is_some() {
363	        return None;
364	    }
365	
366	    let Func { vis, ident, .. } = func;
367	    Some(quote! {
368	        #[doc(hidden)]
369	        #[expect(non_camel_case_types)]
370	        #vis enum #ident {}
371	    })
372	}
373	
374	/// Create the runtime-compatible wrapper closure that parses arguments.
375	fn create_wrapper_closure(func: &Func) -> TokenStream {
376	    // These handlers parse the arguments.
377	    let handlers = {
378	        let func_handlers = func
379	            .params
380	            .iter()
381	            .filter(|param| !param.external)
382	            .map(create_param_parser);
383	        let self_handler = func.special.self_.as_ref().map(create_param_parser);
384	        quote! {
385	            #self_handler
386	            #(#func_handlers)*
387	        }
388	    };
389	
390	    // Throws errors about unexpected arguments.
391	    let finish = (!func.special.args).then(|| quote! { args.take().finish()?; });
392	
393	    // This is the actual function call.
394	    let call = {
395	        let self_ = func
396	            .special
397	            .self_
398	            .as_ref()
399	            .map(bind)
400	            .map(|tokens| quote! { #tokens, });
401	        let engine_ = func.special.engine.then(|| quote! { engine, });
402	        let context_ = func.special.context.then(|| quote! { context, });
403	        let args_ = func.special.args.then(|| quote! { args, });
404	        let span_ = func.special.span.then(|| quote! { args.span, });
405	        let forwarded = func.params.iter().filter(|param| !param.external).map(bind);
406	        quote! {
407	            __typst_func(#self_ #engine_ #context_ #args_ #span_ #(#forwarded,)*)
408	        }
409	    };
410	
411	    // This is the whole wrapped closure.
412	    let ident = &func.ident;
413	    let parent = func.parent.as_ref().map(|ty| quote! { #ty:: });
414	    quote! {
415	        |engine, context, args| {
416	            let __typst_func = #parent #ident;
417	            #handlers
418	            #finish
419	            let output = #call;
420	            #foundations::IntoResult::into_result(output, args.span)
421	        }
422	    }
423	}
424	
425	/// Create a parameter info for a field.
426	fn create_param_info(param: &Param, parent_def_site_key: &str) -> TokenStream {
427	    let Param {
428	        ident, name, docs, named, variadic, ty, default, ..
429	    } = param;
430	    let def_site_key = format!("{parent_def_site_key}::{ident}");
431	    let positional = !named;
432	    let required = !named && default.is_none();
433	    let ty = if *variadic || (*named && default.is_none()) {
434	        quote! { <#ty as #foundations::Container>::Inner }
435	    } else {
436	        quote! { #ty }
437	    };
438	    let default = quote_option(&default.as_ref().map(|_default| {
439	        quote! {
440	            || {
441	                let typed: #ty = #default;
442	                #foundations::IntoValue::into_value(typed)
443	            }
444	        }
445	    }));
446	    quote! {
447	        #foundations::NativeParamInfo {
448	            name: #name,
449	            docs: #docs,
450	            def_site: Some(::typst_utils::DefSite { path: file!(), key: #def_site_key }),
451	            input: <#ty as #foundations::Reflect>::input(),
452	            default: #default,
453	            positional: #positional,
454	            named: #named,
455	            variadic: #variadic,
456	            required: #required,
457	            settable: false,
458	        }
459	    }
460	}
461	
462	/// Create argument parsing code for a parameter.
463	fn create_param_parser(param: &Param) -> TokenStream {
464	    let Param { name, ident, ty, .. } = param;
465	
466	    let mut value = if param.variadic {
467	        quote! { args.all()? }
468	    } else if param.named {
469	        quote! { args.named(#name)? }
470	    } else if param.default.is_some() {
471	        quote! { args.eat()? }
472	    } else {
473	        quote! { args.expect(#name)? }
474	    };
475	
476	    if let Some(default) = &param.default {
477	        value = quote! { #value.unwrap_or_else(|| #default) }
478	    }
479	
480	    quote! { let mut #ident: #ty = #value; }
481	}
482	
483	/// Apply the binding to a parameter.
484	fn bind(param: &Param) -> TokenStream {
485	    let ident = &param.ident;
486	    match param.binding {
487	        Binding::Owned => quote! { #ident },
488	        Binding::Ref => quote! { &#ident },
489	        Binding::RefMut => quote! { &mut #ident },
490	    }
491	}
492	
493	/// Removes attributes and so on from the native function.
494	fn rewrite_fn_item(item: &syn::ItemFn) -> syn::ItemFn {
495	    let inputs = item.sig.inputs.iter().cloned().filter_map(|mut input| {
496	        if let syn::FnArg::Typed(typed) = &mut input {
497	            if typed.attrs.iter().any(|attr| attr.path().is_ident("external")) {
498	                return None;
499	            }
500	            typed.attrs.clear();
501	        }
502	        Some(input)
503	    });
504	    let mut item = item.clone();
505	    item.attrs.clear();
506	    item.sig.inputs = parse_quote! { #(#inputs),* };
507	    item
508	}
